#include <bits/stdc++.h>
using namespace std;

long long dp[65][65];

int main() {
    long long n, t, ans = 0;
    cin >> n >> t;

    if (t <= 0 || (t & (t - 1)) != 0) {
        cout << 0 << '\n';
        return 0;
    }

    long long num = __builtin_ctzll(static_cast<unsigned long long>(t)) + 1;

    if (num == 1) ans--;
    n++;

    for (int i = 0; i <= 60; i++) {
        for (int j = 0; j <= i; j++) {
            if (j == 0)
                dp[i][j] = 1;
            else
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
        }
    }

    for (int i = 60; i >= 0; i--) {
        if (num < 0) break;
        if (n >= (1LL << i)) {
            ans += dp[i][num];
            num--;
            n -= 1LL << i;
        }
    }

    if (num == 0) ans++;
    cout << ans << '\n';

    return 0;
}

